import{_ as e}from"./chunks/会签配置.7xGrdp3p.js";import{_ as t,o as l,c as i,a2 as r}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E6%88%96%E7%AD%BE%E9%85%8D%E7%BD%AE.B2kluHzm.png",o="/newx-doc/assets/%E4%BE%9D%E6%AC%A1%E5%AE%A1%E6%89%B9%E9%85%8D%E7%BD%AE.BNlynw0v.png",s="/newx-doc/assets/Behavior.B8X5j93G.png",p="/newx-doc/assets/BpmParallelMultiInstanceBehavior.D6A8CuvT.png",c="/newx-doc/assets/BpmUserTaskActivityBehavior.r98NaRh3.png",m="/newx-doc/assets/BpmSequentialMultiInstanceBehavior.BAGiOX6o.png",q=JSON.parse('{"title":"会签、或签、依次审批","description":"","frontmatter":{},"headers":[],"relativePath":"bpm/multi-instance.md","filePath":"bpm/multi-instance.md","lastUpdated":null}'),u={name:"bpm/multi-instance.md"};function h(d,a,B,v,_,b){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="会签、或签、依次审批" tabindex="-1">会签、或签、依次审批 <a class="header-anchor" href="#会签、或签、依次审批" aria-label="Permalink to &quot;会签、或签、依次审批&quot;">​</a></h1><p>相关视频：</p><ul><li><a href="https://t.zsxq.com/04yFUVZvF" target="_blank" rel="noreferrer">15、如何实现会签、或签任务？</a></li></ul><p>支持多人审批，包括：</p><ul><li>会签（并行会签）：同一个审批节点设置多个人（如 A、B、C 三人，三人会同时收到待办任务），需全部同意之后，审批才可到下一审批节点</li><li>或签（并行或签）：同一个审批节点设置多个人，任意一个人处理后，就能进入下一个节点</li><li>依次审批（顺序会签）：同一个审批节点设置多个人（如 A、B、C 三人），三人按顺序依次收到待办，即 A 先审批，A 提交后 B 才能审批，需全部同意之后，审批才可到下一审批节点</li></ul><h2 id="_1-多人审批" tabindex="-1">1. 多人审批 <a class="header-anchor" href="#_1-多人审批" aria-label="Permalink to &quot;1. 多人审批&quot;">​</a></h2><h2 id="_1-会签-并行会签" tabindex="-1">1. 会签（并行会签） <a class="header-anchor" href="#_1-会签-并行会签" aria-label="Permalink to &quot;1. 会签（并行会签）&quot;">​</a></h2><p><img src="'+e+'" alt="会签配置"></p><p>实现原理：</p><ul><li>会签配置：并行多重事件，实现多个人同时审批</li><li>完成条件：<code>${ nrOfCompletedInstances &gt;= nrOfInstances }</code>，表示所有人都审批通过，才能进入下一个节点</li></ul><p>疑问：<code>nrOfCompletedInstances</code>、<code>nrOfInstances</code> 表示什么意思？</p><ul><li><code>nrOfCompletedInstances</code>：当前节点已完成的任务数量</li><li><code>nrOfInstances</code>：当前节点总的任务数量</li></ul><p>因此，<code>${ nrOfCompletedInstances &gt;= nrOfInstances }</code> 就是，“已完成”大于“总的”数量，即所有人都审批通过。</p><p>:::</p><h2 id="_2-或签-并行或签" tabindex="-1">2. 或签（并行或签） <a class="header-anchor" href="#_2-或签-并行或签" aria-label="Permalink to &quot;2. 或签（并行或签）&quot;">​</a></h2><p><img src="'+n+'" alt="或签配置"></p><p>实现原理：</p><ul><li>会签配置：并行多重事件，实现多个人同时审批</li><li>完成条件：<code>${ nrOfCompletedInstances == 1 }</code>，表示只要有一个人审批通过，就能进入下一个节点</li></ul><p>因此，会签和或签的差异，就在于完成条件的不同。</p><h2 id="_3-依次审批" tabindex="-1">3. 依次审批 <a class="header-anchor" href="#_3-依次审批" aria-label="Permalink to &quot;3. 依次审批&quot;">​</a></h2><p><img src="'+o+'" alt="依次审批配置"></p><p>实现原理：</p><ul><li>依次审批配置：顺序多重事件，实现多个人按顺序审批</li><li>循环数量：1，表示每次（“循环”）只有一个人审批</li><li>完成条件：<code>${ nrOfCompletedInstances &gt;= nrOfInstances }</code>，表示只要有一个人审批通过，就能进入下一个节点</li></ul><p>因此，依次审批和会签的差异，就在于是否并行审批。</p><hr><p>按照这个思路，实现“票签”，是不是很简单？！</p><p>友情提示：什么是“票签”？</p><p>指同一个审批节点设置多个人，如 A、B、C 三人，当通过比例大于 50% 就能进入下一个节点。</p><p>:::</p><h2 id="_2-实现原理" tabindex="-1">2. 实现原理 <a class="header-anchor" href="#_2-实现原理" aria-label="Permalink to &quot;2. 实现原理&quot;">​</a></h2><p>在 <a href="./assignee">《选择审批人、发起人自选》</a> 小节中，我们看到使用 BpmUserTaskActivityBehavior 实现了审批任务的审批人分配。实际上，还有两个 Behavior 类，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+s+'" alt="Behavior 类图"></p><ul><li><a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-bpm/src/main/java/cn/iocoder/yudao/module/bpm/framework/flowable/core/behavior/BpmParallelMultiInstanceBehavior.java" target="_blank" rel="noreferrer">BpmParallelMultiInstanceBehavior</a> ：并行 + 多实例（单节点多任务）的 Behavior 类</li><li><a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-bpm/src/main/java/cn/iocoder/yudao/module/bpm/framework/flowable/core/behavior/BpmSequentialMultiInstanceBehavior.java" target="_blank" rel="noreferrer">BpmSequentialMultiInstanceBehavior</a> ：顺序 + 多实例（单节点多任务）的 Behavior 类</li></ul><h3 id="_2-1-并行-bpmparallelmultiinstancebehavior" tabindex="-1">2.1 并行 BpmParallelMultiInstanceBehavior <a class="header-anchor" href="#_2-1-并行-bpmparallelmultiinstancebehavior" aria-label="Permalink to &quot;2.1 并行 BpmParallelMultiInstanceBehavior&quot;">​</a></h3><p>① BpmParallelMultiInstanceBehavior 实现 Flowable ParallelMultiInstanceBehavior 类，实现单节点多任务的审批人 <strong>“计算”</strong>。如下图所示：</p><p><img src="'+p+'" alt="BpmParallelMultiInstanceBehavior"></p><p>② BpmUserTaskActivityBehavior，判断是多实例的情况，则复用 BpmParallelMultiInstanceBehavior “计算”结果，直接设置审批人。如下图所示：</p><p><img src="'+c+'" alt="BpmUserTaskActivityBehavior"></p><p>所以，先是 BpmParallelMultiInstanceBehavior 计算审批任务数量 + 审批人列表，然后 BpmUserTaskActivityBehavior 直接设置审批人。</p><h3 id="_2-2-顺序-bpmsequentialmultiinstancebehavior" tabindex="-1">2.2 顺序 BpmSequentialMultiInstanceBehavior <a class="header-anchor" href="#_2-2-顺序-bpmsequentialmultiinstancebehavior" aria-label="Permalink to &quot;2.2 顺序 BpmSequentialMultiInstanceBehavior&quot;">​</a></h3><p>① BpmSequentialMultiInstanceBehavior 实现 Flowable SequentialMultiInstanceBehavior 类，实现单节点多任务的审批人 <strong>“计算”</strong>。如下图所示：</p><p><img src="'+m+'" alt="BpmSequentialMultiInstanceBehavior"></p><p>② 还是使用 BpmUserTaskActivityBehavior，逻辑是一模一样的。</p><p>所以，BpmSequentialMultiInstanceBehavior 和 BpmParallelMultiInstanceBehavior 基本是一致的，差异只是前者返回的是 LinkedHashSet 有序集合。最终，还是交给 Flowable 到底是一次性创建多个审批任务，还是按照顺序创建多个审批任务。</p>',45)])])}const g=t(u,[["render",h]]);export{q as __pageData,g as default};
